lifecycle.insecure:
app.get('/order/:id', requireLogin, async (req,res) => {
  res.json(await db.getOrder(req.params.id));   // any id
});

lifecycle.secure:
app.get('/order/:id', requireLogin, async (req,res) => {
  const o = await db.getOrder(req.params.id);
  if (!o || o.ownerId !== req.user.id) return res.sendStatus(404);
  res.json(o);
});
// centralize this check (policy/middleware) so no route forgets it.
